"""A Zener shunt regulator, as four design functions."""


def zener_output(v_s, r_s, v_z0, r_z, r_load):
    """Regulated output voltage with the Zener modelled as v_z0 in series with r_z."""
    return ((v_s / r_s + v_z0 / r_z)
            / (1.0 / r_s + 1.0 / r_z + 1.0 / r_load))


def zener_current(v_s, r_s, v_z0, r_z, r_load):
    """Current through the Zener, in amps."""
    return (zener_output(v_s, r_s, v_z0, r_z, r_load) - v_z0) / r_z


def line_regulation(v_lo, v_hi, r_s, v_z0, r_z, r_load):
    """Change in output per volt of change in input, dimensionless."""
    hi = zener_output(v_hi, r_s, v_z0, r_z, r_load)
    lo = zener_output(v_lo, r_s, v_z0, r_z, r_load)
    return (hi - lo) / (v_hi - v_lo)


def max_series_resistor(v_s_min, v_out, i_z_min, i_load_max):
    """Largest series resistor that still holds i_z_min at the worst corner."""
    return (v_s_min - v_out) / (i_z_min + i_load_max)


if __name__ == "__main__":
    v = zener_output(12.0, 220.0, 4.94, 8.0, 470.0)
    print("output:", v, "V")
    print("zener current:", zener_current(12.0, 220.0, 4.94, 8.0, 470.0), "A")
    print("no load:", zener_output(12.0, 220.0, 4.94, 8.0, 1e12), "V")
    print("line regulation:", line_regulation(10.0, 14.0, 220.0, 4.94, 8.0, 470.0))
    print("largest R_S for 5 mA at 10 V in and 11 mA out:",
          max_series_resistor(10.0, 5.1, 0.005, 0.011), "ohms")

"""The MOSFET, as a terminal model: which region, how much current, and the slope."""

import math

K = 2e-3      # device transconductance parameter, A/V^2
V_TH = 1.0    # threshold voltage, V
V_A = 45.0    # Early voltage, V


def region(v_gs, v_ds, v_th=V_TH):
    """'cut-off', 'triode' or 'saturation' for these terminal voltages."""
    v_ov = v_gs - v_th
    if v_ov <= 0.0:
        return "cut-off"
    if v_ds < v_ov:
        return "triode"
    return "saturation"


def drain_current(v_gs, v_ds, k=K, v_th=V_TH):
    """Drain current in amperes for these terminal voltages."""
    where = region(v_gs, v_ds, v_th)
    v_ov = v_gs - v_th
    if where == "cut-off":
        return 0.0
    if where == "triode":
        return k * (v_ov * v_ds - v_ds * v_ds / 2.0)
    return k * v_ov * v_ov / 2.0


def transconductance(i_d, k=K):
    """Small-signal transconductance in siemens at this drain current."""
    return math.sqrt(2.0 * k * i_d)


def output_resistance(i_d, v_a=V_A):
    """Small-signal output resistance in ohms at this drain current."""
    return v_a / i_d


if __name__ == "__main__":
    print("at V_GS = 2.0 V, V_DS = 5 V:", region(2.0, 5.0))
    i = drain_current(2.0, 5.0)
    print("drain current:", i, "A")
    print("g_m:", transconductance(i), "S")
    print("r_o:", output_resistance(i), "ohms")
    print("intrinsic gain:", transconductance(i) * output_resistance(i))

